import{_ as t,o as n,c as i,a2 as r}from"./chunks/framework.Buc7gXeZ.js";const u=JSON.parse('{"title":"Portal einbetten","description":"Ein veröffentlichtes Portal in die eigene Website einbinden — inline oder als Fenster.","frontmatter":{"title":"Portal einbetten","description":"Ein veröffentlichtes Portal in die eigene Website einbinden — inline oder als Fenster."},"headers":[],"relativePath":"seiten/portal-einbetten.md","filePath":"seiten/portal-einbetten.md","lastUpdated":1786024399000}'),a={name:"seiten/portal-einbetten.md"};function s(l,e,o,d,h,b){return n(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="portal-einbetten" tabindex="-1">Portal einbetten <a class="header-anchor" href="#portal-einbetten" aria-label="Permalink to &quot;Portal einbetten&quot;">​</a></h1><p>Ein veröffentlichtes Portal lässt sich in die eigene Website einbinden. Besucher bleiben dabei auf Ihrer Seite.</p><p><strong>Voraussetzung:</strong> ein <a href="/docs/seiten/portal-veroeffentlichen">Portal-Link</a>. Ohne ihn gibt es nichts einzubetten.</p><h2 id="einbettungscode-erzeugen" tabindex="-1">Einbettungscode erzeugen <a class="header-anchor" href="#einbettungscode-erzeugen" aria-label="Permalink to &quot;Einbettungscode erzeugen&quot;">​</a></h2><p>Wählen Sie im Freigabedialog <strong>Auf Ihrer Webseite einbinden</strong>. Es öffnet sich <em>Seite einbinden</em>.</p><p>Den fertigen Code finden Sie unter <em>Embed code</em>. Kopieren Sie ihn an die gewünschte Stelle Ihrer Website.</p><h2 id="einbindungsart" tabindex="-1">Einbindungsart <a class="header-anchor" href="#einbindungsart" aria-label="Permalink to &quot;Einbindungsart&quot;">​</a></h2><p>Drei Möglichkeiten:</p><table tabindex="0"><thead><tr><th>Art</th><th>Verhalten</th></tr></thead><tbody><tr><td><strong>Inline (in der Seite)</strong></td><td>Das Portal sitzt fest im Seitenfluss, wie ein Bild oder Video</td></tr><tr><td><strong>Fenster (unten links)</strong></td><td>Ein Button öffnet das Portal in einem überlagernden Fenster</td></tr><tr><td><strong>Fenster (unten rechts)</strong></td><td>Dasselbe, rechts positioniert</td></tr></tbody></table><h3 id="inline" tabindex="-1">Inline <a class="header-anchor" href="#inline" aria-label="Permalink to &quot;Inline&quot;">​</a></h3><p>Für Inhalte, die zur Seite gehören: eine Übersicht im Kundenbereich, ein Anmeldeformular auf der Veranstaltungsseite, eine Preisliste.</p><p>Einstellungen: <strong>Breite</strong>, <strong>Höhe</strong> und <strong>Höhe automatisch anpassen</strong> (<em>Die Höhe wird automatisch an den Seiteninhalt angepasst</em>).</p><div class="tip custom-block"><p class="custom-block-title">Höhe automatisch anpassen aktivieren</p><p>Ohne diese Option bekommt das eingebettete Portal eine feste Höhe. Bei aufklappenden Bereichen, Tabs oder längeren Tabellen entsteht dann ein Scrollbalken innerhalb des Rahmens — auf Mobilgeräten schlecht bedienbar.</p></div><h3 id="fenster" tabindex="-1">Fenster <a class="header-anchor" href="#fenster" aria-label="Permalink to &quot;Fenster&quot;">​</a></h3><p>Ein Button am Bildschirmrand öffnet das Portal überlagernd. Für Dinge, die jederzeit erreichbar sein sollen, ohne die Seite zu dominieren: Rückmeldungen, Support-Anfragen, Störungsmeldungen.</p><p>Einstellungen: <strong>Button-Text</strong> (Vorgabe <em>Feedback</em>) und <strong>Button-Farbe</strong>.</p><div class="tip custom-block"><p class="custom-block-title">Position nach Layout wählen</p><p><em>Unten rechts</em> ist der übliche Platz für Hilfe- und Chat-Elemente — dort erwarten Nutzer so etwas. Wählen Sie <em>unten links</em>, wenn rechts bereits ein Cookie-Hinweis, ein Chat-Widget oder ein Nach-oben-Button sitzt.</p></div><h2 id="vorschau" tabindex="-1">Vorschau <a class="header-anchor" href="#vorschau" aria-label="Permalink to &quot;Vorschau&quot;">​</a></h2><p>Über <strong>Vorschau</strong> prüfen Sie das Ergebnis, bevor Sie den Code einbauen.</p><h2 id="was-sie-auf-ihrer-website-beachten-sollten" tabindex="-1">Was Sie auf Ihrer Website beachten sollten <a class="header-anchor" href="#was-sie-auf-ihrer-website-beachten-sollten" aria-label="Permalink to &quot;Was Sie auf Ihrer Website beachten sollten&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Das Portal bleibt eigenständig</p><p>Der eingebettete Inhalt kommt von ApptiveGrid, nicht von Ihrem Server. Praktische Folgen:</p><ul><li>Ihre Website-Stile wirken <strong>nicht</strong> auf das Portal. Gestaltung erfolgt in den <a href="/docs/seiten/seite-erstellen">Seiteneinstellungen</a>.</li><li>Die Zugriffsbeschränkung des Portal-Links gilt auch eingebettet. Ist <em>Mit Anmeldeinformationen</em> gesetzt, erscheint die Anmeldemaske im Rahmen.</li><li>Blockiert der Browser eines Besuchers Inhalte von Drittanbietern, bleibt der Rahmen leer.</li></ul></div><div class="warning custom-block"><p class="custom-block-title">Datenschutzhinweis prüfen</p><p>Beim Einbetten werden Inhalte von einem externen Dienst geladen, und Besucher geben unter Umständen personenbezogene Daten in ein eingebettetes Formular ein. Prüfen Sie, ob Ihre Datenschutzerklärung das abdeckt — insbesondere bei einem Fenster-Widget, das auf jeder Seite mitläuft.</p></div><h2 id="typische-fehler" tabindex="-1">Typische Fehler <a class="header-anchor" href="#typische-fehler" aria-label="Permalink to &quot;Typische Fehler&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Ursache</th></tr></thead><tbody><tr><td>Rahmen bleibt leer</td><td>Kein Portal-Link vorhanden oder er wurde gelöscht</td></tr><tr><td>Anmeldemaske statt Inhalt</td><td>Der Link ist auf <em>Mit Anmeldeinformationen</em> beschränkt</td></tr><tr><td>Scrollbalken im Rahmen</td><td><em>Höhe automatisch anpassen</em> ist aus</td></tr><tr><td>Auf dem Smartphone abgeschnitten</td><td>Feste Breite im Einbettungscode; besser relative Breite</td></tr><tr><td>Portal zeigt zu viele Daten</td><td>Die eingebettete Ansicht ist nicht ausreichend gefiltert</td></tr></tbody></table><h2 id="formular-statt-portal-einbetten" tabindex="-1">Formular statt Portal einbetten <a class="header-anchor" href="#formular-statt-portal-einbetten" aria-label="Permalink to &quot;Formular statt Portal einbetten&quot;">​</a></h2><p>Formulare haben einen eigenen Einbettungsweg mit ähnlichen Einstellungen. Für reine Datenerfassung ist das der direktere Weg.</p><p>→ <a href="/docs/formulare/formular-teilen">Formular teilen</a></p><h2 id="weiter" tabindex="-1">Weiter <a class="header-anchor" href="#weiter" aria-label="Permalink to &quot;Weiter&quot;">​</a></h2><ul><li><a href="/docs/seiten/portal-veroeffentlichen">Portal veröffentlichen</a></li><li><a href="/docs/zusammenarbeit/zugriff-beschraenken">Zugriff auf geteilte Inhalte</a></li><li><a href="/docs/seiten/seitenlayout">Seitenlayout</a></li></ul>',29)])])}const m=t(a,[["render",s]]);export{u as __pageData,m as default};
